+++ w/internal/oci/oci.go
@@ -8,10 +8,15 @@ import (
 	"fmt"
 	"io"
 	"net/http"
+	"net/url"
 	"path"
 	"strings"
+	"time"
 )

+// templateClientTimeout bounds one whole request of Client, body included.
+const templateClientTimeout = time.Minute
+
 // Client handles OCI registry operations
 type Client struct {
 	registryURL string
@@ -19,6 +24,11 @@ type Client struct {
 	REDACTED    string
 	httpClient  *http.Client

+	// blobClient fetches the layer blob only. Unlike httpClient it follows a
+	// redirect to another origin (a registry that hands blobs to a CDN or an
+	// object store), but never with credentials: see followBlobRedirect.
+	blobClient *http.Client
+
 	// Limits bounds a template download; the zero value is unbounded.
 	Limits Limits
 }
@@ -43,24 +53,131 @@ func NewClient(registryURL, username, REDACTED string) *Client {
 		registryURL: strings.TrimSuffix(registryURL, "/"),
 		username:    username,
 		REDACTED:    REDACTED,
-		httpClient:  &http.Client{},
+		httpClient:  &http.Client{Timeout: templateClientTimeout, CheckRedirect: RefuseOffOriginRedirect},
+		blobClient:  &http.Client{Timeout: templateClientTimeout, CheckRedirect: followBlobRedirect},
 	}
 }

+// errBlobRedirectScheme is the refusal of a blob redirect to anything but
+// http or https. It names no URL: the target may be signed.
+var errBlobRedirectScheme = errors.New("refusing redirect to a scheme other than http or https")
+
+// followBlobRedirect is the CheckRedirect of Client.blobClient.
+//
+// Deliberate exception to RefuseOffOriginRedirect (DEVDESK-412, user decision
+// Q1b): a layer blob may be served from another origin, the usual way a registry
+// hands it to a CDN or an object store. The redirect is followed, but the
+// credentials never go with it:
+//   - at most MaxRedirects hops, only to http or https;
+//   - never from https to http, so a signed URL does not leave in clear;
+//   - once the chain left the origin of the first request (scheme, host and
+//     port), Authorization is deleted from every following request, including
+//     one that comes back to the origin. net/http copies the header to the same
+//     host name on another port, across a scheme change and to a subdomain, and
+//     it copies it before this function runs, so deleting it here is what counts.
+func followBlobRedirect(req *http.Request, via []*http.Request) error {
+	if len(via) >= MaxRedirects {
+		return ErrTooManyRedirects
+	}
+	if req.URL.Scheme != "http" && req.URL.Scheme != "https" {
+		return errBlobRedirectScheme
+	}
+	first := via[0].URL
+	if first.Scheme == "https" && req.URL.Scheme != "https" {
+		return fmt.Errorf("%w (%s)", errInsecureRedirect, req.URL.Host)
+	}
+	left := !sameOrigin(first.String(), req.URL.String())
+	for _, prev := range via[1:] {
+		left = left || !sameOrigin(first.String(), prev.URL.String())
+	}
+	if left {
+		req.Header.Del("Authorization")
+	}
+	return nil
+}
+
+// blobFetchError rewrites a *url.Error of the blob download so that it carries
+// the host of the failing hop at most: its URL may hold a signed query or a
+// private path. The cause stays reachable through errors.Is and errors.As.
+func blobFetchError(err error) error {
+	var ue *url.Error
+	if !errors.As(err, &ue) {
+		return err
+	}
+	if u, perr := url.Parse(ue.URL); perr == nil && u.Host != "" {
+		return fmt.Errorf("download layer from %s: %w", u.Host, ue.Err)
+	}
+	return fmt.Errorf("download layer: %w", ue.Err)
+}
+
+// blobCap bounds the compressed bytes taken off the network for one layer: the
+// content limit, a tar header and padding per file, and 1 MiB of gzip framing.
+// The decompressed Limits do not see everything the network carries (a
+// directory entry with a large size is skipped without being counted), so this
+// is the only bound on those bytes. 0 means no cap (Limits{} or no byte limit).
+func blobCap(lim Limits) int64 {
+	if lim.Bytes <= 0 {
+		return 0
+	}
+	return lim.Bytes + int64(lim.Files)*2048 + 1<<20
+}
+
+// cappedReader reads from r, accepting at most left bytes: one more byte
+// available makes it fail with ErrArchiveTooLarge instead of reading it.
+type cappedReader struct {
+	r    io.Reader
+	left int64
+}
+
+func (c *cappedReader) Read(p []byte) (int, error) {
+	if len(p) == 0 {
+		return 0, nil
+	}
+	if c.left <= 0 {
+		var probe [1]byte
+		n, err := c.r.Read(probe[:])
+		if n > 0 {
+			return 0, ErrArchiveTooLarge
+		}
+		return 0, err
+	}
+	if int64(len(p)) > c.left {
+		p = p[:c.left]
+	}
+	n, err := c.r.Read(p)
+	c.left -= int64(n)
+	return n, err
+}
+
+// get sends a GET to rawURL through client, with Basic auth when both the
+// username and the REDACTED are set and an Accept header when accept is not
+// empty. The caller closes the body. A refused redirect comes back through
+// StripRedirectTarget, so no target URL (possibly signed) reaches an error.
+func (c *Client) get(client *http.Client, rawURL, accept string) (*http.Response, error) {
+	req, err := http.NewRequest("GET", rawURL, nil)
+	if err != nil {
+		return nil, err
+	}
+
+	if accept != "" {
+		req.Header.Set("Accept", accept)
+	}
+	if c.username != "" && c.REDACTED != "" {
+		req.SetBasicAuth(c.username, c.REDACTED)
+	}
+
+	resp, err := client.Do(req)
+	if err != nil {
+		return nil, StripRedirectTarget(err)
+	}
+	return resp, nil
+}
+
 // ListTags lists available tags for a repository (templates)
 func (c *Client) ListTags(repository string) ([]string, error) {
 	url := fmt.Sprintf("%s/v2/%s/tags/list", c.registryURL, repository)

-	req, err := http.NewRequest("GET", url, nil)
-	if err != nil {
-		return nil, err
-	}
-
-	if c.username != "" && c.REDACTED != "" {
-		req.SetBasicAuth(c.username, c.REDACTED)
-	}
-
-	resp, err := c.httpClient.Do(req)
+	resp, err := c.get(c.httpClient, url, "")
 	if err != nil {
 		return nil, err
 	}
@@ -86,17 +203,7 @@ func (c *Client) DownloadTemplate(repository, tag string) (*Template, error) {
 	// Get manifest
 	manifestURL := fmt.Sprintf("%s/v2/%s/manifests/%s", c.registryURL, repository, tag)

-	req, err := http.NewRequest("GET", manifestURL, nil)
-	if err != nil {
-		return nil, err
-	}
-
-	req.Header.Set("Accept", "application/vnd.oci.image.manifest.v1+json")
-	if c.username != "" && c.REDACTED != "" {
-		req.SetBasicAuth(c.username, c.REDACTED)
-	}
-
-	resp, err := c.httpClient.Do(req)
+	resp, err := c.get(c.httpClient, manifestURL, "application/vnd.oci.image.manifest.v1+json")
 	if err != nil {
 		return nil, err
 	}
@@ -139,18 +246,9 @@ func (c *Client) DownloadTemplate(repository, tag string) (*Template, error) {
 func (c *Client) downloadAndExtractLayer(repository, digest string) ([]ArchiveFile, error) {
 	url := fmt.Sprintf("%s/v2/%s/blobs/%s", c.registryURL, repository, digest)

-	req, err := http.NewRequest("GET", url, nil)
+	resp, err := c.get(c.blobClient, url, "")
 	if err != nil {
-		return nil, err
-	}
-
-	if c.username != "" && c.REDACTED != "" {
-		req.SetBasicAuth(c.username, c.REDACTED)
-	}
-
-	resp, err := c.httpClient.Do(req)
-	if err != nil {
-		return nil, err
+		return nil, blobFetchError(err)
 	}
 	defer func() { _ = resp.Body.Close() }()

@@ -158,7 +256,11 @@ func (c *Client) downloadAndExtractLayer(repository, digest string) ([]ArchiveFi
 		return nil, fmt.Errorf("failed to download layer: %s", resp.Status)
 	}

-	return ReadTarGzLimited(resp.Body, c.Limits)
+	var body io.Reader = resp.Body
+	if limit := blobCap(c.Limits); limit > 0 {
+		body = &cappedReader{r: resp.Body, left: limit}
