359	// paddedTarGz builds a small archive of three tiny files, each preceded by a
360	// PAX header carrying 500 KiB of seeded random (incompressible) padding. The
361	// padding is neither file content nor counted by Limits, so only a cap on the
362	// bytes taken off the network sees it: about 1.5 MiB in all.
363	func paddedTarGz(t *testing.T) []byte {
364		t.Helper()
365		const (
366			files   = 3
367			padSize = 500 << 10
368		)
369		rng := rand.New(rand.NewSource(412))
370		var buf bytes.Buffer
371		gzw := gzip.NewWriter(&buf)
372		tw := tar.NewWriter(gzw)
373		for i := range files {
374			pad := make([]byte, padSize)
375			_, _ = rng.Read(pad)
376			hdr := &tar.Header{
377				Name:       fmt.Sprintf("f%d.txt", i),
378				Mode:       0o644,
379				Size:       2,
380				Typeflag:   tar.TypeReg,
381				Format:     tar.FormatPAX,
382				PAXRecords: map[string]string{"DEVDESK.pad": string(pad)},
383			}
384			if err := tw.WriteHeader(hdr); err != nil {
385				t.Fatalf("writing header %d: %v", i, err)
386			}
387			if _, err := tw.Write([]byte("hi")); err != nil {
388				t.Fatalf("writing body %d: %v", i, err)
389			}
390		}
391		if err := tw.Close(); err != nil {
392			t.Fatalf("closing tar: %v", err)
393		}
394		if err := gzw.Close(); err != nil {
395			t.Fatalf("closing gzip: %v", err)
396		}
397		if buf.Len() > 2<<20 {
398			t.Fatalf("fixture is %d bytes, keep it under 2 MiB", buf.Len())
399		}
400		return buf.Bytes()
401	}
