403	// 8. The compressed bytes taken off the network are capped, even when what the
404	// archive declares as content stays within Limits.
405	func TestBlobByteCap(t *testing.T) {
406		archive := paddedTarGz(t)
407		lim := Limits{Files: 10, Bytes: 1 << 10}
408		if int64(len(archive)) <= blobCap(lim) {
409			t.Fatalf("fixture (%d bytes) is not over blobCap (%d), the test checks nothing", len(archive), blobCap(lim))
410		}
411	
412		t.Run("blobCap formula", func(t *testing.T) {
413			if got, want := blobCap(lim), int64(1<<10+10*2048+1<<20); got != want {
414				t.Errorf("blobCap(%+v) = %d, want %d", lim, got, want)
415			}
416			if got := blobCap(Limits{}); got != 0 {
417				t.Errorf("blobCap(zero) = %d, want 0 (no cap)", got)
418			}
419		})
420	
421		t.Run("redirected blob over the cap", func(t *testing.T) {
422			var aHits, bHits hitLog
423			b := archiveHost(t, false, &bHits, archive)
424			a := blobRegistry(t, false, &aHits, redirectTo(b.URL+"/blob?"+blobSignedQuery))
425	
426			c := NewClient(a.URL, clientTestUser, clientTestPass)
427			c.Limits = lim
428			tpl, err := c.DownloadTemplate("tpl", "v1")
429	
430			if !errors.Is(err, ErrArchiveTooLarge) {
431				t.Fatalf("err = %v, want errors.Is ErrArchiveTooLarge", err)
432			}
433			if tpl != nil {
434				t.Errorf("template = %+v, want nil", tpl)
435			}
436		})
437	
438		t.Run("same archive without limits is read", func(t *testing.T) {
439			var aHits, bHits hitLog
440			b := archiveHost(t, false, &bHits, archive)
441			a := blobRegistry(t, false, &aHits, redirectTo(b.URL+"/blob?"+blobSignedQuery))
